CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Inline device helper: Mish -> add -> Hardtanh([-1,1]) -> scale
__device__ __forceinline__ float apply_transform(float x, float add_value, float scale) {
    float sp = x > 20.0f ? x : __logf(1.0f + __expf(x));
    x = x * tanhf(sp) + add_value;
    x = fmaxf(-1.0f, fminf(1.0f, x));
    return x * scale;
}

// Fused epilogue: each thread processes TWO float4 groups to increase ILP
// and hide memory latency by issuing both loads before computing either.
__global__ void fused_mish_add_hardtanh_scale_kernel(
    float* __restrict__ data,
    int64_t n4,        // number of float4 groups
    int64_t remainder, // leftover scalar elements (0-3)
    float add_value,
    float scale
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t i0 = idx * 2;
    int64_t i1 = i0 + 1;

    float4* ptr4 = reinterpret_cast<float4*>(data);

    if (i0 < n4) {
        // Issue both loads upfront so memory latency overlaps with computation
        float4 v0 = ptr4[i0];
        float4 v1;
        bool has_v1 = (i1 < n4);
        if (has_v1) v1 = ptr4[i1];

        // Compute all 4 components of v0
        v0.x = apply_transform(v0.x, add_value, scale);
        v0.y = apply_transform(v0.y, add_value, scale);
        v0.z = apply_transform(v0.z, add_value, scale);
        v0.w = apply_transform(v0.w, add_value, scale);

        // Compute all 4 components of v1 if it exists
        if (has_v1) {
            v1.x = apply_transform(v1.x, add_value, scale);
            v1.y = apply_transform(v1.y, add_value, scale);
            v1.z = apply_transform(v1.z, add_value, scale);
            v1.w = apply_transform(v1.w, add_value, scale);
        }

        // Store both results
        ptr4[i0] = v0;
        if (has_v1) ptr4[i1] = v1;
    }

    // Handle scalar remainder (at most 3 elements); threads 0..remainder-1 cover these
    int64_t base = n4 * 4;
    if (idx < remainder) {
        float x = data[base + idx];
        float sp = x > 20.0f ? x : __logf(1.0f + __expf(x));
        x = x * tanhf(sp) + add_value;
        x = fmaxf(-1.0f, fminf(1.0f, x));
        data[base + idx] = x * scale;
    }
}

void fused_epilogue(torch::Tensor x, float add_value, float scale) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");

    int64_t numel = x.numel();
    int64_t n4 = numel / 4;
    int64_t remainder = numel % 4;

    // Grid covers ceil(n4/2) threads (two float4 per thread) or at least remainder threads
    int64_t n_threads_needed = (n4 + 1) / 2;
    if (n_threads_needed < remainder) n_threads_needed = remainder;

    int64_t nthreads = 256;
    int64_t nblocks = (n_threads_needed + nthreads - 1) / nthreads;
    if (nblocks == 0 && (n4 > 0 || remainder > 0)) nblocks = 1;

    if (nblocks > 0) {
        fused_mish_add_hardtanh_scale_kernel<<<nblocks, nthreads>>>(
            x.data_ptr<float>(),
            n4,
            remainder,
            add_value,
            scale
        );
    }
}
